def calculate_worst_case_response_time(task_i, all_jobs_of_task_i):
    max_response_time = 0
    for job_p in all_jobs_of_task_i:
        response_time_p = job_p.completion_time - job_p.activation_time
        if response_time_p > max_response_time:
            max_response_time = response_time_p
    return max_response_time

class Task:
    def __init__(self, transaction_id, task_id_in_transaction, offset, wcet, jitter):
        self.transaction_id = transaction_id
        self.task_id_in_transaction = task_id_in_transaction
        self.phi = offset # phi_i_j
        self.C = wcet     # C_i_j
        self.J = jitter   # J_i_j

class Transaction:
    def __init__(self, transaction_id, period, tasks):
        self.id = transaction_id
        self.T = period
        self.tasks = sorted(tasks, key=lambda t: t.phi) # Ordered by offset
